from supaflow.cli import main

if __name__ == "__main__":
    main()

from datetime import datetime, timezone
from pathlib import Path


def store_root() -> Path:
    return Path.home() / ".supaflow"


def projects_root() -> Path:
    return store_root() / "projects"


def project_key_for_cwd() -> str:
    cwd = Path.cwd().resolve()
    parent = cwd.parent.name or "_root"
    name = cwd.name or "_root"
    return f"{parent}/{name}"


def project_dir(key: str) -> Path:
    return projects_root() / key


def now_iso() -> str:
    return datetime.now(timezone.utc).isoformat(timespec="seconds")

