resource "aws_ecs_express_gateway_service" "backend" {
  service_name            = "${var.project}-${var.environment}-backend-v3"
  execution_role_arn      = aws_iam_role.ecs_task_execution.arn
  infrastructure_role_arn = aws_iam_role.ecs_infrastructure_express.arn
  health_check_path       = "/admin/login/"

  primary_container {
    image          = "${aws_ecr_repository.backend.repository_url}:latest"
    container_port = 8000

    environment {
      name  = "CORS_ALLOWED_ORIGINS"
      value = var.frontend_origin
    }
    environment {
      name  = "IS_LOCAL"
      value = "False"
    }
    environment {
      name  = "PROD_DATABASE_URL"
      value = "postgres://${var.db_username}:${var.db_password}@${aws_db_instance.postgres.endpoint}/financexpo?sslmode=require"
    }
    environment {
      name  = "DJANGO_ALLOWED_HOSTS"
      value = "*"
    }
    environment {
      name  = "DJANGO_DEBUG"
      value = "False"
    }
    environment {
      name  = "DJANGO_SECRET_KEY"
      value = var.django_secret_key
    }
    environment {
      name  = "GOOGLE_OAUTH_CLIENT_ID"
      value = var.google_oauth_client_id
    }
    environment {
      name  = "GOOGLE_OAUTH_CLIENT_SECRET"
      value = var.google_oauth_client_secret
    }
    environment {
      name  = "KAPSO_API_KEY"
      value = var.kapso_api_key
    }
    environment {
      name  = "KAPSO_API_URL"
      value = var.kapso_api_url
    }
    environment {
      name  = "RESEND_API_KEY"
      value = var.resend_api_key
    }
    environment {
      name  = "RESEND_WEBHOOK_SECRET"
      value = var.resend_webhook_secret
    }
    environment {
      name  = "SUPABASE_WEBHOOK_SECRET"
      value = var.supabase_webhook_secret
    }
    # TEMPORARY: two-DB mirror. Drop once the Supabase + Postgres DBs are
    # consolidated. See backend/contacts/services/supabase_mirror.py.
    environment {
      name  = "SUPABASE_URL"
      value = var.supabase_url
    }
    environment {
      name  = "SUPABASE_KEY"
      value = var.supabase_key
    }
  }
}

resource "aws_ecs_express_gateway_service" "agent" {
  service_name            = "${var.project}-${var.environment}-agent-v2"
  execution_role_arn      = aws_iam_role.ecs_task_execution.arn
  infrastructure_role_arn = aws_iam_role.ecs_infrastructure_express.arn
  health_check_path       = "/health"

  primary_container {
    image          = "${aws_ecr_repository.agent.repository_url}:latest"
    container_port = 8001

    environment {
      name  = "AWS_BEARER_TOKEN_BEDROCK"
      value = var.aws_bearer_token_bedrock
    }
    environment {
      name  = "AWS_REGION"
      value = var.region
    }
    environment {
      name  = "BEDROCK_MODEL_ID"
      value = var.bedrock_model_id
    }
    environment {
      name  = "KAPSO_API_URL"
      value = "https://api.kapso.ai/meta/whatsapp/v24.0"
    }
    environment {
      name  = "KAPSO_PLATFORM_URL"
      value = "https://api.kapso.ai/platform/v1"
    }
    environment {
      name  = "KAPSO_API_KEY"
      value = var.kapso_api_key
    }
    environment {
      name  = "KAPSO_PHONE_NUMBER_ID"
      value = var.kapso_phone_number_id
    }
    environment {
      name  = "WEBHOOK_SECRET"
      value = var.webhook_secret
    }
    environment {
      name  = "LOGFIRE_TOKEN"
      value = var.logfire_token
    }
    environment {
      name  = "LOGFIRE_ENVIRONMENT"
      value = var.environment
    }
  }
}

data "aws_vpc" "default" {
  default = true
}

data "aws_subnets" "default" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
}

resource "aws_security_group" "rds" {
  name        = "${var.project}-rds-v2"
  description = "Postgres access for ${var.project}"
  vpc_id      = data.aws_vpc.default.id

  # Open to the internet for V1 — ECS Express talks to RDS over public IP.
  # Tighten this (peer security groups or VPC endpoints) before prod.
  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "postgres" {
  name       = "${var.project}-postgres-v2"
  subnet_ids = data.aws_subnets.default.ids
}

resource "aws_db_instance" "postgres" {
  identifier              = "${var.project}-${var.environment}-v2"
  engine                  = "postgres"
  engine_version          = "16.3"
  instance_class          = "db.t4g.micro"
  allocated_storage       = 20
  storage_type            = "gp3"
  storage_encrypted       = true
  db_name                 = "financexpo"
  username                = var.db_username
  password                = var.db_password
  db_subnet_group_name    = aws_db_subnet_group.postgres.name
  vpc_security_group_ids  = [aws_security_group.rds.id]
  publicly_accessible       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${var.project}-${var.environment}-v2-final"
  deletion_protection       = true
  backup_retention_period   = 7
}

