  # Optional safety guard so you can't apply against the wrong account.
  # Leave aws_account_id = "" to disable; set your 12-digit id to enforce.
  allowed_account_ids = var.aws_account_id != "" ? [var.aws_account_id] : null

  default_tags {
    tags = {
      Project     = var.project
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  }
}

