def parse_gate(name: str) -> tuple[tuple[str | None, str | None], str]:
    """Detect a presence gate encoded in a filename and strip it.

    A file may carry one gating segment among its dot-separated parts:
      - ``.empty``        -> fallback: emitted only if no active ``.when-<part>``
                             variant claims the same output name.
      - ``.when-<part>``  -> emitted only if ``<part>`` is in the scaffold.
    Returns ``((kind, part), base_name)`` where kind is "empty" | "when" | None
    and base_name is the filename with the gating segment removed.
    """
    segs = name.split(".")
    for i, s in enumerate(segs):
        if s == "empty":
            return ("empty", None), ".".join(segs[:i] + segs[i + 1 :])
        if s.startswith("when-") and len(s) > len("when-"):
            return ("when", s[len("when-") :]), ".".join(segs[:i] + segs[i + 1 :])
    return (None, None), name


def copy_parts_module(
    src_module: Path, dest_module: Path, parts: list[str], always: list[str] = ()
) -> None:
    dest_module.mkdir(parents=True, exist_ok=True)
    order = ["_core", *always, *parts]
    present = set(parts)

    # Pass 1: which output names are claimed by an active .when-<part> variant?
    # A claimed name suppresses the matching .empty fallback in pass 2.
    claimed: set[str] = set()
    for part in order:
        pdir = src_module / part
        if not pdir.is_dir():
            continue
        for f in iter_files(pdir):
            (kind, dep), base = parse_gate(f.name)
            if kind == "when" and dep in present:
                claimed.add(f.relative_to(pdir).with_name(base).as_posix())

    # Pass 2: emit in order, resolving gates to their de-gated output path.
    tfvars_chunks: list[str] = []
    for part in order:
        pdir = src_module / part
        if not pdir.is_dir():
            continue
        for f in iter_files(pdir):
            (kind, dep), base = parse_gate(f.name)
            rel = f.relative_to(pdir)
            if kind == "when":
                if dep not in present:
                    continue
                rel = rel.with_name(base)
            elif kind == "empty":
                rel = rel.with_name(base)
                if rel.as_posix() in claimed:
                    continue
            # De-gating done; now classify by the resolved output name.
            if rel.name.endswith(".tfvars.fragment"):
                tfvars_chunks.append(f.read_text(encoding="utf-8").rstrip("\n"))
                continue
            out = dest_module / rel
            out.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(f, out)
    if tfvars_chunks:
        body = "\n\n".join(tfvars_chunks) + "\n"
        (dest_module / "terraform.tfvars.example").write_text(body, encoding="utf-8")

