// DB wiring when this scaffold ALSO includes the rds part. The URL is built
// live from the RDS box created in this same stack, so a single `terraform
// apply` stands up the database and injects its endpoint into the service —
// Terraform's dependency graph orders rds before ecs for you.
//
// newsetup emits this file ONLY when rds is selected (the `.when-rds` gate).
// When rds is absent, db_local.empty.tf supplies a var-driven fallback instead.
// The two files define the same `local.database_url`; exactly one is ever copied.
locals {
  database_url = "postgres://${var.db_username}:${var.db_password}@${aws_db_instance.postgres.endpoint}/${replace(var.project, "-", "_")}?sslmode=require"
}

// DB wiring when this scaffold has NO rds part. The service points at whatever
// external database you supply via var.database_url (Supabase, Neon, an RDS in
// another stack, ...). Inert by default (empty string) so `ecs` alone still
// validates and applies.
//
// newsetup emits this file ONLY when rds is absent (the `.empty` fallback gate).
// When rds is present, db_local.when-rds.tf wins and builds the URL from the
// live RDS endpoint instead. The two files define the same `local.database_url`;
// exactly one is ever copied.
variable "database_url" {
  description = "Full backend database connection string, e.g. postgres://user:pass@host:5432/db?sslmode=require. Used only when no in-stack rds part provides it."
  type        = string
  default     = ""
}

locals {
  database_url = var.database_url
}

